import sys, types, json, hashlib
from pathlib import Path
import sympy, mpmath
runtime = {}
for package in (sympy, mpmath):
    path = Path(package.__file__)
    runtime[package.__name__] = {'version': package.__version__, 'origin': str(path), 'initializer_sha256': hashlib.sha256(path.read_bytes()).hexdigest()}
runtime['claim'] = 'Observed package versions/origins/initializer identities; no entire third-party runtime verification.'
Path('SYMPY-RUNTIME.json').write_text(json.dumps(runtime, indent=2, sort_keys=True)+'\n')
if sympy.__version__ != '1.14.0' or mpmath.__version__ != '1.3.0':
    print(json.dumps({'result_valid': False, 'error': 'LAW scientific runtime version mismatch'}))
    sys.exit(1)
